    68	export const updateLeaveRequestSchema = z.object({
    69	  leaveType: z.enum([
    70	    LeaveType.annual,
    71	    LeaveType.sick,
    72	    LeaveType.emergency,
    73	  ]).optional(),
    74	  startDate: z.coerce.date().optional(),
    75	  endDate: z.coerce.date().optional(),
    76	  reason: z.string().optional(),
    77	  status: z.enum([
    78	    LeaveStatus.draft,
    79	    LeaveStatus.submitted,
    80	    LeaveStatus.approved,
    81	    LeaveStatus.rejected,
    82	    LeaveStatus.cancelled,
    83	  ]).optional(),
